pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum) public {
        // Bound value to reasonable range for fuzzing
        value = bound(value, 1, 100 ether);
        // Assume block number is at least 1
        vm.assume(blockNum > 0);
        // We'll simulate a specific block number
        vm.roll(blockNum);
        // Set timestamp to something increasing
        vm.warp(blockNum * 10);

        // Try to call fallback with given value
        (bool success, ) = address(c).call{value: value}("");

        // If call succeeded, check the rule
        if (success) {
            // The call only succeeds when msg.value == 10 ether and block.timestamp > pastBlockTime
            // After success, if block.number % 15 != 0, the balance stays at 10 ether
            // We need to check: when block.number % 15 != 0, the balance should be >= 10 ether (since we just added 10)
            assertTrue(address(c).balance >= 10 ether || blockNum % 15 == 0);
        } else {
            // If call reverted, the rule holds vacuously
            assertTrue(true);
        }
    }
}

