pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, uint256 blockNumber) public {
        // Bound blockNumber to something reasonable
        blockNumber = bound(blockNumber, 1, 1000);
        // Simulate a block number
        vm.roll(blockNumber);
        vm.warp(block.timestamp + 1); // ensure timestamp > pastBlockTime

        // Record caller balance before
        uint256 callerBalanceBefore = address(this).balance;
        // Deal 10 ether to this contract to send
        vm.deal(address(this), 10 ether);
        // Call fallback with 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success);
        uint256 callerBalanceAfter = address(this).balance;

        // The rule: if block.number % 15 == 0, the caller gets back the full contract balance (which includes the 10 ether just sent)
        // If not, the caller gets nothing back
        if (blockNumber % 15 == 0) {
            // The caller's increase should be the contract balance after the call (since transfer sends everything)
            assertTrue(callerBalanceAfter - callerBalanceBefore == address(c).balance);
        } else {
            // The caller should have lost exactly 10 ether (the sent value) minus nothing returned
            assertTrue(callerBalanceAfter == callerBalanceBefore - 10 ether);
        }
    }
}

