pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, uint256 initialBalance) public {
        // Ensure initialBalance is a multiple of 10 ether for reference correctness
        vm.assume(initialBalance % 10 ether == 0);

        // Set the block number
        vm.roll(blockNumber);

        // Set contract balance to initialBalance
        vm.deal(address(c), initialBalance);

        // Record balance before fallback call
        uint256 balBefore = address(c).balance;

        // Call fallback with exactly 10 ether (must succeed due to require)
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Ensure call succeeded (require(msg.value == 10 ether) satisfied)
        require(success, "fallback must succeed with 10 ether");

        // Get balance after call
        uint256 balAfter = address(c).balance;

        // Compute change
        uint256 change;
        if (balAfter >= balBefore) {
            change = balAfter - balBefore;
        } else {
            change = balBefore - balAfter;
        }

        // The change must be either 0 (no transfer) or balBefore (full transfer)
        assertTrue(change == 0 || change == balBefore);
    }
}

