// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 100 ether);
        vm.deal(address(c), 10 ether);
        uint256 balanceBefore = address(c).balance;

        // Only calls with exactly 10 ether are accepted by the fallback
        if (amount == 10 ether) {
            (bool success, ) = address(c).call{value: amount}("");
            if (success) {
                uint256 balanceAfter = address(c).balance;
                // After a successful fallback, balance must be less than before (due to possible transfer) or equal (if no transfer)
                assertTrue(balanceAfter <= balanceBefore, "Balance should not increase");
            } else {
                // If it reverts, balance must be unchanged
                assertTrue(address(c).balance == balanceBefore, "Balance unchanged on revert");
            }
        } else {
            // If amount is not 10 ether, the call should revert, balance unchanged
            (bool success, ) = address(c).call{value: amount}("");
            assertTrue(!success, "Call must revert for non-10 ether amounts");
            assertTrue(address(c).balance == balanceBefore, "Balance unchanged on revert");
        }
    }
}

