pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 timeJump) public {
        amount = bound(amount, 10 ether, 10 ether);
        timeJump = bound(timeJump, 1, 1e6);

        uint256 balanceBefore = address(c).balance;
        vm.assume(balanceBefore > 0); // ensure contract has some balance for transfer

        // warp to satisfy timestamp condition
        vm.warp(block.timestamp + timeJump);

        uint256 callerBalanceBefore = address(this).balance;

        // call fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: amount}("");

        // If call succeeded, the transfer may have occurred (if block.number % 15 == 0)
        // The rule: caller's ether balance must not decrease
        uint256 callerBalanceAfter = address(this).balance;
        assertTrue(callerBalanceAfter >= callerBalanceBefore);
    }
}

