pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 time1, uint256 time2) public {
        vm.assume(time1 < type(uint40).max);
        vm.assume(time2 < type(uint40).max && time2 > time1);
        vm.warp(time1);
        vm.deal(address(this), 100 ether);
        uint256 callerBalBefore = address(this).balance;
        uint256 contractBalBefore = address(c).balance;

        // First call to set pastBlockTime
        (bool success1, ) = address(c).call{value: 10 ether}("");
        vm.assume(success1);

        vm.warp(time2);
        // Second call that may trigger transfer
        (bool success2, ) = address(c).call{value: 10 ether}("");
        vm.assume(success2);

        uint256 callerBalAfter = address(this).balance;
        uint256 contractBalAfter = address(c).balance;

        bool transferOccurred = (callerBalAfter == callerBalBefore - 10 ether + contractBalBefore) && 
                                 (contractBalAfter == 0);
        bool notTransfer = (callerBalAfter == callerBalBefore - 20 ether) && 
                           (contractBalAfter == contractBalBefore + 10 ether);
        assertTrue(transferOccurred || notTransfer);
    }
}
